CREATE TABLE IF NOT EXISTS "user" ("id" text PRIMARY KEY, "name" text NOT NULL, "email" text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, "image" text, "role" text NOT NULL DEFAULT 'user', "banned" boolean NOT NULL DEFAULT false, "banReason" text, "banExpires" timestamptz, "twoFactorEnabled" boolean NOT NULL DEFAULT false, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "one_portfolio_admin" ON "user" ("role") WHERE "role" = 'admin';
CREATE TABLE IF NOT EXISTS "session" ("id" text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, "token" text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "impersonatedBy" text);
CREATE INDEX IF NOT EXISTS "session_user_id_idx" ON "session" ("userId");
CREATE TABLE IF NOT EXISTS "account" ("id" text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "account_user_id_idx" ON "account" ("userId");
CREATE TABLE IF NOT EXISTS "verification" ("id" text PRIMARY KEY, "identifier" text NOT NULL, "value" text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "rateLimit" ("id" text PRIMARY KEY, "key" text NOT NULL, "count" integer NOT NULL, "lastRequest" bigint NOT NULL);
CREATE INDEX IF NOT EXISTS "rateLimit_key_idx" ON "rateLimit" ("key");
CREATE TABLE IF NOT EXISTS "twoFactor" ("id" text PRIMARY KEY, "userId" text NOT NULL UNIQUE REFERENCES "user"("id") ON DELETE CASCADE, "secret" text NOT NULL, "backupCodes" text NOT NULL, "verified" boolean NOT NULL DEFAULT false, "failedVerificationCount" integer NOT NULL DEFAULT 0, "lockedUntil" timestamptz);
CREATE TABLE IF NOT EXISTS "posts" ("id" text PRIMARY KEY, "slug" text NOT NULL UNIQUE, "title" text NOT NULL, "description" text NOT NULL, "bodyMarkdown" text NOT NULL, "status" text NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'published')), "tags" jsonb NOT NULL DEFAULT '[]'::jsonb, "readTime" text, "coverImage" text, "coverImageAlt" text, "seoTitle" text, "seoDescription" text, "canonicalUrl" text, "socialImage" text, "publishedAt" timestamptz, "authorId" text NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "post_cover_alt_pair" CHECK ("coverImage" IS NULL OR length(trim("coverImageAlt")) > 0));
CREATE INDEX IF NOT EXISTS "posts_status_published_idx" ON "posts" ("status", "publishedAt" DESC);
CREATE TABLE IF NOT EXISTS "feedback" ("id" text PRIMARY KEY, "message" text NOT NULL, "category" text NOT NULL DEFAULT 'general' CHECK ("category" IN ('general', 'bug', 'accessibility', 'content')), "status" text NOT NULL DEFAULT 'new' CHECK ("status" IN ('new', 'reviewed', 'archived')), "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "feedback_status_created_idx" ON "feedback" ("status", "createdAt" DESC);
CREATE TABLE IF NOT EXISTS "feedback_rate_limits" ("key_hash" text PRIMARY KEY, "window_started_at" timestamptz NOT NULL, "count" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "audit_events" ("id" text PRIMARY KEY, "actor_id" text NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT, "action" text NOT NULL, "entity_type" text NOT NULL, "entity_id" text NOT NULL, "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "audit_created_idx" ON "audit_events" ("created_at" DESC);
CREATE TABLE IF NOT EXISTS "resources" ("id" text PRIMARY KEY, "slug" text NOT NULL UNIQUE, "title" text NOT NULL, "description" text NOT NULL, "author" text, "category" text NOT NULL CHECK ("category" IN ('learning', 'tools', 'reading', 'media')), "url" text NOT NULL, "coverImage" text, "coverImageAlt" text, "status" text NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'published')), "seoTitle" text, "seoDescription" text, "authorId" text NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "resource_cover_alt_pair" CHECK ("coverImage" IS NULL OR length(trim("coverImageAlt")) > 0));
CREATE INDEX IF NOT EXISTS "resources_category_status_idx" ON "resources" ("category", "status");
CREATE TABLE IF NOT EXISTS "bootstrap_attempts" ("key_hash" text PRIMARY KEY, "window_started_at" timestamptz NOT NULL, "count" integer NOT NULL);

CREATE TABLE IF NOT EXISTS "bootstrap_claim" ("id" text PRIMARY KEY CHECK ("id" = 'owner'), "created_at" timestamptz NOT NULL DEFAULT now());
